      clave: [['Pull-down', 'Resistor de la entrada a GND que fija un 0 cuando el botón está abierto'], ['ULN2003', 'Circuito integrado con 7 transistores Darlington y diodos para manejar bobinas'], ['Tierra común', 'Unión del GND del Arduino con el 0 V de la fuente del tablero'], ['Tabla de pines', 'Relación entre los pines físicos y las direcciones del PLC en OpenPLC'], ['Optoacoplador', 'Componente que pasa una señal con luz y aísla dos circuitos']],
      ejemplo: { titulo: 'Conectar el botón de arranque y la bobina de K1', pasos: ['Botón S1 entre +5 V y el pin de %IX0.1; 10 kΩ del pin a GND.', 'Pin de %QX0.0 → entrada 1 del ULN2003.', 'Salida 1 del ULN2003 → A2 de K1; A1 de K1 → +12 V.', 'COM del ULN2003 a +12 V; GND del ULN2003 y del Arduino al 0 V.'], resultado: 'El programa enciende %QX0.0 y K1 se energiza con 12 V sin que el Arduino toque ese voltaje.' },
      preguntas: [['¿Por qué un pin del Arduino no puede energizar directo una bobina de 12 V?', 'Porque trabaja a 5 V y entrega unos 20 mA; la bobina pide 12 V y más corriente.'], ['¿Para qué sirve el resistor de 10 kΩ del pin a GND?', 'Para que la entrada lea 0 con seguridad cuando el botón está abierto (pull-down).'], ['¿Qué pasa si falta la tierra común?', 'Las señales no tienen referencia y las salidas no funcionan o se comportan raro.'], ['¿Cómo entra un sensor de 12 V al Arduino?', 'Por un contacto de relevador o un optoacoplador, nunca directo.']],
      errores: ['Conectar 12 V a un pin del Arduino: se daña.', 'Olvidar la tierra común.', 'Dejar entradas sin pull-down: leen al azar.', 'Usar un módulo de relevadores que se activa con LOW sin darse cuenta.'],
