  const cto = (x, y, nc, conduce) => ln([x - 10, y - 12], [x - 10, y + 12], 'k3') + ln([x + 10, y - 12], [x + 10, y + 12], 'k3') + (nc ? ln([x - 15, y + 12], [x + 15, y - 12], 'k2') : '') + (conduce ? ln([x - 10, y], [x + 10, y], 'a') : '');
  const bob = (x, y, on, lb) => ci([x, y], 16, on ? 'fillA' : 'none3') + tx([x, y + 5], lb, 'tb');
  const LUZ = { v: 'rgba(28,160,80,.85)', a: 'rgba(240,160,0,.9)', r: 'rgba(210,40,40,.9)' };
