      s += W([160, 80], [200, 80], true) + cto(210, 80, false, eA) + W([220, 80], [270, 80], eA) + cto(280, 80, false, ARR === 1) + W([290, 80], [414, 80], eB) + bob(430, 80, eB, 'M') + W([446, 80], [460, 80], false);
      s += W([245, 80], [245, 130], eA) + W([245, 130], [270, 130], eA) + cto(280, 130, false, k) + W([290, 130], [320, 130], eB) + W([320, 130], [320, 80], eB);
      s += tx([210, 58], 'PARO', 'tb') + tx([280, 58], 'ARRANQUE', 'tb') + tx([280, 156], 'MOTOR (memoria)', 'tm') + tx([430, 112], 'MOTOR', 'tm');
      s += W([160, 195], [200, 195], true) + cto(210, 195, false, k) + W([220, 195], [414, 195], k) + bob(430, 195, k, 'L') + W([446, 195], [460, 195], false) + tx([210, 175], 'MOTOR', 'tb') + tx([418, 228], 'LUZ_MARCHA', 'tm');
      const cap = ph < 2 ? 'Reposo: PARO vale 1 y su contacto NA deja pasar' : ph < 3 ? 'ARRANQUE = 1: se activa MOTOR' : ph < 6 ? 'MOTOR se mantiene por su propio contacto' : ph < 7 ? 'Presionas S0: PARO = 0 y MOTOR se apaga' : 'Reposo otra vez';
      return s + tx([240, 246], cap, 'tb');
