      [[70, 'ARRANQUE'], [136, 'TON 10 s'], [200, 'TON 3 s']].forEach(r => { s += ln([X - 12, r[0]], [X + 12, r[0]], 'k3') + tx([X + 20, r[0] + 5], r[1], 'tm', 'start'); });
      s += ln([118, 170], [142, 170], 'k3') + tx([112, 175], 'TON 10 s', 'tm', 'end');
      [[1, 'VERDE'], [2, 'ÁMBAR'], [3, 'ROJO']].forEach(a => { s += ln([X + 17, Y[a[0]] + 17], [X + 110, Y[a[0]] + 17], 'k2') + rc(X + 110, Y[a[0]] + 3, 70, 28, act === a[0] ? 'fillA' : 'fill2', 3) + tx([X + 145, Y[a[0]] + 22], a[1], act === a[0] ? 'ta' : 'tb'); });
